"""Leakage-bounded semantic relation prompts."""

from __future__ import annotations

import json

from .contracts import RELATION_STATES
from .semantic_cases import CASES, SemanticCase


SYSTEM_PROMPT = """You are a stateless semantic relation assessor.
Judge only the relation between each pair of evidence packets under the stated
target scope. Do not calculate probabilities or propose composition, selection,
acceptance, retention, or publication actions. Return JSON only."""

STATE_DEFINITIONS = {
    "INDEPENDENT_DISTINCT": (
        "Distinct evidence generated by independent observation paths after "
        "conditioning on the target state."
    ),
    "EXACT_DUPLICATE": (
        "The packets restate the same underlying observation or source item; "
        "counting both would duplicate evidence."
    ),
    "DEPENDENT_DISTINCT": (
        "The packets are not exact copies but their observations are dependent "
        "through shared data, derivation, model, or measurement process."
    ),
    "PARTIAL_OVERLAP": (
        "The packets share only part of their observations, subjects, studies, "
        "or source material."
    ),
    "SCOPE_INCOMPATIBLE": (
        "At least one packet concerns a population, time, intervention, or "
        "configuration incompatible with the stated target scope."
    ),
    "UNRESOLVED": (
        "Available descriptors are insufficient to distinguish independence, "
        "duplication, dependence, overlap, or scope compatibility."
    ),
}


def _definitions(order: tuple[str, ...]) -> list[dict[str, str]]:
    return [
        {"relation_state": state, "definition": STATE_DEFINITIONS[state]}
        for state in order
    ]


def _schema_example() -> dict[str, object]:
    return {
        "case_id": "R43B-01",
        "relation_state": "ONE_ALLOWED_RELATION_STATE",
        "evidence_refs": [
            "descriptor://case/left",
            "descriptor://case/right",
        ],
        "unresolved_assumptions": [],
    }


def batch_prompt(replicate: str) -> str:
    cases = CASES if replicate == "A" else tuple(reversed(CASES))
    states = RELATION_STATES if replicate == "A" else tuple(reversed(RELATION_STATES))
    payload = {
        "relation_definitions": _definitions(states),
        "required_receipt_schema": _schema_example(),
        "cases": [case.public_dict() for case in cases],
    }
    return (
        "Classify every case using exactly one defined relation state. Cite "
        "exactly the two descriptor evidence_refs from that case. Put unknown "
        "facts only in unresolved_assumptions. Return a JSON object with a "
        "receipts array, or a top-level receipt array.\n"
        + json.dumps(payload, ensure_ascii=True, sort_keys=True)
    )


def single_prompt(case: SemanticCase, index: int) -> str:
    rotation = index % len(RELATION_STATES)
    states = RELATION_STATES[rotation:] + RELATION_STATES[:rotation]
    payload = {
        "relation_definitions": _definitions(states),
        "required_receipt_schema": _schema_example(),
        "case": case.public_dict(),
    }
    return (
        "Classify this case using exactly one defined relation state. Cite "
        "exactly its two descriptor evidence_refs. Put unknown facts only in "
        "unresolved_assumptions. Return one receipt as a JSON object, a receipts "
        "object, or a one-item array.\n"
        + json.dumps(payload, ensure_ascii=True, sort_keys=True)
    )
